/**
 * Applies the ease draft to the host, safely, for both surfaces.
 *
 * - Live is debounced (150 ms) and fires only on completed changes.
 * - The selection signature is captured when an apply is scheduled and sent as
 *   `expectedSelection`; the host refuses a stale one before writing, and a
 *   response that arrives after the selection changed is discarded here too.
 * - Keyframes generated by points/bake come back as a `session`; sending it on
 *   the next apply lets the host replace them instead of multiplying them.
 * - One host call is one native Undo (the dispatcher opens the group).
 */
import type { CommandResponse } from "@motion/contracts";
import { easeCommandArgs, type EaseDraft, type EaseSession, validEaseSession } from "./ease-args.js";
import type { EaseApplyLock, EaseOrigin } from "./ease-sync.js";

export type EaseApplyOutcome =
  | { kind: "applied"; appliedCount: number; removedCount: number; session: EaseSession | null; quiet: boolean }
  | { kind: "noChange"; quiet: boolean }
  | { kind: "stale"; quiet: boolean }
  | { kind: "conflict"; response: CommandResponse; quiet: boolean }
  | { kind: "failed"; response: CommandResponse; quiet: boolean }
  | { kind: "discarded"; reason: "selection" | "busy" | "lock" | "disabled" | "invalid"; quiet: boolean };

export type EaseCancelReason = "selection" | "close" | "escape" | "live-off";

export interface EaseApplyData { appliedCount?: number; skippedCount?: number; removedCount?: number; session?: unknown }

export interface EaseControllerDeps {
  origin: EaseOrigin;
  execute(args: Record<string, unknown>): Promise<CommandResponse<EaseApplyData>>;
  draft(): EaseDraft;
  selectionSignature(): string | null;
  /** Why an apply must not run now (no selection, needs a pair…); null when allowed. */
  disabledReason(): string | null;
  /** Something else is writing to the host (any tool). */
  busy(): boolean;
  setBusy(busy: boolean, quiet: boolean): void;
  /** Returns true when an invalid field should block the apply (focus it). */
  invalidInput?(): boolean;
  report(outcome: EaseApplyOutcome): void;
  lock?: EaseApplyLock;
  liveDelayMs?: number;
  now?(): number;
}

export interface EaseController {
  apply(options?: { quiet?: boolean }): Promise<EaseApplyOutcome>;
  scheduleLive(): void;
  cancelPending(reason: EaseCancelReason): void;
  session(): EaseSession | null;
  setSession(session: EaseSession | null): void;
  onSelectionSignature(signature: string | null): void;
  pending(): boolean;
  dispose(): void;
}

export function createEaseController(deps: EaseControllerDeps): EaseController {
  let session: EaseSession | null = null;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let queued = false;
  let scheduledSignature: string | null | undefined;
  let lastSignature: string | null = deps.selectionSignature();
  let disposed = false;
  const delay = deps.liveDelayMs ?? 150;

  function clearTimer(): void { if (timer !== undefined) clearTimeout(timer); timer = undefined; }

  async function apply(options: { quiet?: boolean } = {}): Promise<EaseApplyOutcome> {
    const quiet = Boolean(options.quiet);
    const finish = (outcome: EaseApplyOutcome): EaseApplyOutcome => { deps.report(outcome); return outcome; };
    if (disposed) return { kind: "discarded", reason: "disabled", quiet };
    if (deps.busy()) { if (quiet) queued = true; return { kind: "discarded", reason: "busy", quiet }; }
    if (deps.disabledReason()) return { kind: "discarded", reason: "disabled", quiet };
    if (deps.invalidInput?.()) return { kind: "discarded", reason: "invalid", quiet };
    if (deps.lock && !deps.lock.acquire(deps.origin, deps.now?.())) {
      if (quiet) { queued = true; scheduleLive(); }
      return { kind: "discarded", reason: "lock", quiet };
    }
    const expected = deps.selectionSignature();
    const args = easeCommandArgs(deps.draft(), { expectedSelection: expected, session });
    deps.setBusy(true, quiet);
    try {
      const response = await deps.execute(args);
      if (disposed) return { kind: "discarded", reason: "disabled", quiet };
      // A late answer for a selection that no longer exists is not news about this one.
      if (deps.selectionSignature() !== expected) return finish({ kind: "discarded", reason: "selection", quiet });
      if (!response.ok) {
        const code = response.error?.code;
        if (code === "STALE_SELECTION") { session = null; return finish({ kind: "stale", quiet }); }
        if (code === "KEYFRAME_CONFLICT") return finish({ kind: "conflict", response, quiet });
        return finish({ kind: "failed", response, quiet });
      }
      const data = response.data ?? {};
      const next = validEaseSession(data.session) ? data.session : null;
      session = next;
      const applied = data.appliedCount ?? 0, removed = data.removedCount ?? 0;
      if (applied > 0 || removed > 0) return finish({ kind: "applied", appliedCount: applied, removedCount: removed, session: next, quiet });
      return finish({ kind: "noChange", quiet });
    } catch {
      return finish({ kind: "failed", response: { protocolVersion: 1, requestId: "", ok: false, data: null, warnings: [], error: null }, quiet });
    } finally {
      deps.lock?.release(deps.origin);
      deps.setBusy(false, quiet);
      if (queued && !disposed) { queued = false; scheduleLive(); }
    }
  }

  function scheduleLive(): void {
    if (disposed) return;
    clearTimer();
    scheduledSignature = deps.selectionSignature();
    timer = setTimeout(() => {
      timer = undefined;
      if (disposed || !deps.draft().live) return;
      // The selection moved on since the gesture: that result belongs to nobody.
      if (deps.selectionSignature() !== scheduledSignature) { deps.report({ kind: "discarded", reason: "selection", quiet: true }); return; }
      if (deps.busy()) { queued = true; return; }
      void apply({ quiet: true });
    }, delay);
  }

  function cancelPending(reason: EaseCancelReason): void {
    clearTimer(); queued = false;
    if (reason === "selection" || reason === "close") scheduledSignature = undefined;
  }

  return {
    apply, scheduleLive, cancelPending,
    pending: () => timer !== undefined || queued,
    session: () => session,
    setSession(next) { session = next && validEaseSession(next) ? next : null; },
    onSelectionSignature(signature) {
      if (signature === lastSignature) return;
      lastSignature = signature;
      cancelPending("selection");
      if (session && session.signature !== signature) session = null;
    },
    dispose() { disposed = true; clearTimer(); queued = false; }
  };
}
